#!/usr/bin/env sh
# Print a .env with fresh random secrets for the DEV-ONLY docker-compose
# example. docker-compose.yml has no secret defaults and refuses to start
# without these.
#
#   ./gen-env.sh > .env
#
# Regenerating rotates every secret; `docker compose down -v` first so
# postgres re-initialises with the new password.
set -eu

command -v openssl >/dev/null 2>&1 || { echo "error: openssl is required" >&2; exit 1; }

cat <<EOF
# Generated by gen-env.sh. DEV ONLY: never reuse these outside this example.

# HMAC key for the device-flow session cookie: base64url, 32 random bytes.
TEMPOGATE_SESSION_SIGNING_KEY=$(openssl rand -base64 32 | tr '+/' '-_' | tr -d '=')
# Confidential client secrets (OIDC_CLIENT_SECRETS).
TEMPORAL_UI_CLIENT_SECRET=$(openssl rand -hex 32)
TEMPOGATE_DEVICE_UI_CLIENT_SECRET=$(openssl rand -hex 32)
# Temporal's postgres password.
POSTGRES_PASSWORD=$(openssl rand -hex 24)

# Optional, non-secret knobs (defaults shown).
# DEMO_EMAIL=alice@example.com
# DEMO_HD=example.com
# TEMPOGATE_ALLOWED_DOMAINS=example.com
# TEMPOGATE_ALLOWED_HOSTED_DOMAINS=example.com
# LOG_LEVEL=info

# Optional: encrypt signing keys at rest. Once set, tempogate needs it to start.
# TEMPOGATE_KEYS_ENCRYPTION_KEY=$(openssl rand -base64 32)
EOF
